/**
 * Botón oficial «Añadir a Google Wallet» (versión principal, negro), tal cual
 * lo da Google: no se dibuja ni se retoca (normas de marca). Se sirve desde
 * nuestro dominio (GET /w/assets/google-wallet/:lang).
 *
 * Origen: https://developers.google.com/static/wallet/download-assets/add-to-wallet-svg.zip
 * (enlazado desde https://developers.google.com/wallet/generic/resources/brand-guidelines).
 * Ficheros: esES_, enGB_, frFR_ y pt_add_to_google_wallet_wallet-button.svg (el de portugués es el
 * único que da Google: «Adicionar a Carteira do Google»).
 * Generado con un script a partir del zip: si Google cambia el botón, se
 * vuelve a generar (la prueba comprueba el sha256 de cada fichero).
 */

export interface GoogleWalletButton {
  /** Fichero del zip oficial. */
  file: string;
  /** sha256 del fichero oficial (la prueba comprueba que no se ha tocado). */
  sha256: string;
  width: number;
  height: number;
  /** Texto alternativo (lo que dice el botón). */
  alt: string;
  svg: string;
}

